150→// AssertCheckpointAdvanced asserts the checkpoint branch moved forward.
151→func AssertCheckpointAdvanced(t *testing.T, s *RepoState) {
152→	t.Helper()
153→	after := GitOutput(t, s.Dir, "rev-parse", "entire/checkpoints/v1")
154→	assert.NotEqual(t, s.CheckpointBefore, after, "checkpoint branch did not advance")
155→}
