200→// AssertCheckpointExists asserts that the checkpoint ID is mentioned on
201→// the checkpoint branch and that its metadata.json exists in the tree.
202→func AssertCheckpointExists(t *testing.T, dir string, checkpointID string) {
203→	t.Helper()
