357→// FilterAndNormalizePaths converts absolute paths to relative and filters out
358→// infrastructure paths and paths outside the repo.
359→func FilterAndNormalizePaths(files []string, cwd string) []string {
360→	var result []string
361→	for _, file := range files {
362→		relPath := paths.ToRelativePath(file, cwd)
363→		if relPath == "" {
364→			continue // outside repo
365→		}
366→		if paths.IsInfrastructurePath(relPath) {
367→			continue // skip .entire directory
368→		}
369→		result = append(result, filepath.ToSlash(relPath))
370→	}
371→	return result
372→}
