374→// mergeUnique appends elements from extra into base, skipping duplicates already in base.
375→func mergeUnique(base, extra []string) []string {
376→	if len(extra) == 0 {
377→		return base
378→	}
379→	seen := make(map[string]bool, len(base))
380→	for _, s := range base {
381→		seen[s] = true
382→	}
383→	for _, s := range extra {
384→		if !seen[s] {
385→			seen[s] = true
386→			base = append(base, s)
387→		}
388→	}
389→	return base
390→}
