func filterToUncommittedFiles(ctx context.Context, files []string, repoRoot string) []string {
	if len(files) == 0 {
		return files
	}

	repo, err := openRepository(ctx)
	if err != nil {
		return files // fail open
	}

	head, err := repo.Head()
	if err != nil {
		return files // fail open (empty repo, detached HEAD, etc.)
	}

	commit, err := repo.CommitObject(head.Hash())
	if err != nil {
		return files // fail open
	}

	headTree, err := commit.Tree()
	if err != nil {
		return files // fail open
	}

	var result []string
	for _, relPath := range files {
		headFile, err := headTree.File(relPath)
		if err != nil {
			// File not in HEAD — it's uncommitted
			result = append(result, relPath)
			continue
		}

		// File is in HEAD — compare content with working tree
		absPath := filepath.Join(repoRoot, relPath)
		workingContent, err := os.ReadFile(absPath) //nolint:gosec // path from controlled source
		if err != nil {
			// Can't read working tree file (deleted?) — keep it
			result = append(result, relPath)
			continue
		}

		headContent, err := headFile.Contents()
		if err != nil {
			result = append(result, relPath)
			continue
		}

		// Normalize CRLF → LF on both sides so the comparison works on Windows
		// where core.autocrlf may convert line endings on checkout. Git blobs
		// store raw bytes and are not guaranteed to use LF line endings.
		normalizedWorking := strings.ReplaceAll(string(workingContent), "\r\n", "\n")
		normalizedHead := strings.ReplaceAll(headContent, "\r\n", "\n")
		if normalizedWorking != normalizedHead {
			// Working tree differs from HEAD — uncommitted changes
			result = append(result, relPath)
		}
		// else: content matches HEAD — already committed, skip
	}

	return result
}

